import { AsyncLocalStorage } from 'node:async_hooks';
const security = new AsyncLocalStorage();          // set once after authentication
export const guard = (policy) => (req, res, next) => {
  const ctx = security.getStore();                 // subject + attributes
  const d = policy(ctx, req.method, req.path);     // pure, deny by default
  if (!d.allow) {
    auditDenied(ctx, d.reason);
    return res.status(403).json({ reason: d.reason });
  }
  next();                                          // downstream code is rule-free
};
